import sys
from datetime import date, timedelta

RATE = {"book": 0.5, "dvd": 1.0, "magazine": 0.2}

def parse(text):
    y, m, d = map(int, text.split("-"))
    return date(y, m, d)

def adjust_due_date(due_date):
    due = parse(due_date)
    if due.weekday() == 6:  # Sunday is 6
        due += timedelta(days=1)
    return due

def compute_late_days(due_date, return_date=None, asof_date=None):
    due = adjust_due_date(due_date)
    if return_date:
        return (parse(return_date) - due).days
    if asof_date:
        return (parse(asof_date) - due).days
    return 0

def main():
    lines = sys.stdin.read().splitlines()
    if not lines:
        return
    asof_line = lines[0]
    asof_date = parse(asof_line.split()[1])
    totals = {}
    for line in lines[1:]:
        if not line.strip():
            continue
        member, kind, due_date_str, returned = line.split()
        if returned == "-":
            return_date = None
        else:
            return_date = returned
        late_days = compute_late_days(due_date_str, return_date, asof_date)
        if late_days > 0:
            fee = max(0, late_days - 3) * RATE[kind]
            fee = min(fee, 10.00)
            totals[member] = totals.get(member, 0.0) + fee
    for member in sorted(totals.keys()):
        print(f"{member} {totals[member]:.2f}")
    print(f"total {sum(totals.values()):.2f}")

if __name__ == "__main__":
    main()
